  IF got IS DISTINCT FROM ARRAY['SalesPersonID', 'FullName', 'JobTitle', 'SalesTerritory', '2002', '2003', '2004']::text[] THEN
    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 01 fiscal year = order year + 6 months: 07-01 starts the next year, 06-30 23:59:59.997 does not, 08-31 c…', got, ARRAY['SalesPersonID', 'FullName', 'JobTitle', 'SalesTerritory', '2002', '2003', '2004']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
